--
-- Regenerate with:  npm run seed:generate
-- Source of truth:  data/animals.ts
--
-- Idempotent: re-running updates each species in place (matched on slug), so it is
-- safe to apply repeatedly and safe to run after editing the dataset.
-- ===========================================================================

insert into public.animals (
  id,
  slug,
  name,
  latin_name,
  category,
  habitat,
  region,
  conservation_status,
  diet,
  description,
  fun_facts,
  model_url,
  image_url,
  sound_url,
  scale_ratio,
  weight_kg,
  length_m,
  height_m,
  lifespan_years,
  is_prehistoric,
  premium,
  accent,
  emoji,
  silhouette,
  popularity
)
values
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000001', 'african-bush-elephant', 'African Bush Elephant', 'Loxodonta africana', 'Mammal', 'African savanna, bush & woodland', 'Africa', 'Endangered', 'Herbivore', 'The largest living land animal, the African bush elephant moves across the savanna in matriarch-led herds that share knowledge of waterholes across generations. Its dexterous trunk fuses the nose and upper lip, and its huge ears act as radiators that dump heat into the shade.', array['An elephant''s trunk contains roughly 40,000 muscles, far more than a human body has.', 'The ears can be flapped to shed heat and are shaped a little like the African continent.', 'Elephants dig for water with their tusks and trunk, creating pools other species rely on.', 'A calf can stand within an hour of birth and is protected by the whole herd.']::text[], '/models/african-bush-elephant.glb', null, null, 3.2, 6000, 6.5, 3.2, '60-70 years', false, false, array['#9aa3a8', '#3a3a3c']::text[], '🐘', 'quadruped', 96),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000002', 'axolotl', 'Axolotl', 'Ambystoma mexicanum', 'Amphibian', 'Freshwater canals & lakes of Xochimilco, Mexico', 'North America', 'Critically Endangered', 'Carnivore', 'The axolotl is a salamander that never grows up: it keeps its feathery larval gills and stays aquatic for life. Once abundant in the canals of Xochimilco, wild numbers have collapsed as the waterways are drained, polluted and stocked with introduced fish.', array['It can regenerate whole limbs, its tail, and parts of its heart and brain without scarring.', 'Keeping juvenile features into adulthood is called neoteny, and the axolotl is its famous example.', 'Its name comes from Xolotl, the Aztec god associated with transformation and death.', 'Wild axolotls survive only in the Xochimilco canal system on the southern edge of Mexico City.']::text[], '/models/axolotl.glb', null, null, 0.25, 0.15, 0.25, 0.08, '10-15 years', false, false, array['#f2a0c0', '#2b1b2e']::text[], '🦎', 'quadruped', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000003', 'bald-eagle', 'Bald Eagle', 'Haliaeetus leucocephalus', 'Bird', 'Lakeshores, rivers & coasts of North America', 'North America', 'Least Concern', 'Piscivore', 'A sea eagle of North American waterways, the bald eagle snatches fish from the surface with talons that lock shut on contact. Its white head and tail only appear at about five years old, which is why the national bird is also called the white-headed eagle.', array['Wingspan can reach 2.3 metres, yet the skeleton weighs less than the bird''s feathers.', 'Its stick nests are among the largest built by any bird and are reused and enlarged for years.', 'The name comes from an old sense of bald meaning white-headed, not hairless.', 'A hunting eagle can stoop through the air at close to 160 km/h.']::text[], '/models/bald-eagle.glb', null, '/sounds/bald-eagle.mp3', 0.9, 5, 0.9, 0.7, '20-30 years', false, false, array['#f5f1e6', '#3b2a1a']::text[], '🦅', 'bird', 94),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000004', 'bengal-tiger', 'Bengal Tiger', 'Panthera tigris', 'Mammal', 'Indian mangroves, grassland & dry forest', 'Asia', 'Endangered', 'Carnivore', 'The Bengal tiger is the classic striped big cat of the Indian subcontinent, hunting deer and wild boar alone across territories that can span a hundred square kilometres. In the Sundarbans it swims between mangrove islands, a rare skill among cats.', array['Every tiger''s stripe pattern is unique, and the skin beneath the fur is striped too.', 'A tiger''s roar can be heard about 3 km away in still forest air.', 'Tigers are strong swimmers and readily cross rivers and mangrove channels.', 'They are solitary ambush hunters that can drag prey heavier than themselves.']::text[], '/models/bengal-tiger.glb', null, null, 3.1, 220, 3.1, 1.1, '10-15 years', false, false, array['#e07b2a', '#1d1a17']::text[], '🐅', 'quadruped', 98),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000005', 'blue-whale', 'Blue Whale', 'Balaenoptera musculus', 'Mammal', 'Open ocean, feeding in cold polar seas', 'Oceans', 'Endangered', 'Filter Feeder', 'The largest animal known to have lived, the blue whale sieves swarms of krill through baleen plates the size of fence slats. It feeds in cold, rich polar waters in summer and migrates thousands of kilometres toward the tropics to breed.', array['Its heart can weigh around 180 kg, about as much as a small car engine.', 'The tongue alone can weigh as much as an adult elephant.', 'A blue whale can eat up to four tonnes of krill in a single day.', 'Its low-frequency calls exceed 180 decibels and travel for hundreds of kilometres underwater.']::text[], '/models/blue-whale.glb', null, '/sounds/blue-whale.ogg', 27, 130000, 27, 4.5, '80-90 years', false, false, array['#3a6fb0', '#12233d']::text[], '🐋', 'whale', 97),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000006', 'common-octopus', 'Common Octopus', 'Octopus vulgaris', 'Cephalopod', 'Coastal reefs, seagrass & rocky seabeds', 'Oceans', 'Data Deficient', 'Carnivore', 'A soft-bodied hunter with eight sucker-lined arms, the common octopus slips into rock crevices that no fish can follow. It changes colour and skin texture in a fraction of a second, vanishing into reef and rubble before a predator arrives.', array['It has three hearts and copper-based blood that is blue when oxygenated.', 'Chromatophore cells let it change colour and texture faster than a blink.', 'It swims by jet propulsion, expelling water through a steerable siphon.', 'A female guards her eggs without feeding and dies shortly after they hatch.']::text[], '/models/common-octopus.glb', null, null, 1, 3, 1, 0.3, '1-2 years', false, false, array['#d1665e', '#3a1f2b']::text[], '🐙', 'marine', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000007', 'emperor-penguin', 'Emperor Penguin', 'Aptenodytes forsteri', 'Bird', 'Antarctic sea ice & pack ice colonies', 'Antarctica', 'Endangered', 'Piscivore', 'The tallest penguin breeds on Antarctic sea ice in the middle of the polar winter, when temperatures drop below -50 degrees Celsius. Males balance a single egg on their feet under a brood pouch for two months while the females are away hunting at sea.', array['Emperor penguins have been recorded diving deeper than 500 metres.', 'Males fast for around two months while incubating, losing nearly half their body weight.', 'Thousands of birds huddle in tight groups that constantly shuffle so everyone takes a turn in the warm centre.', 'They cannot fly, but swim at about 6 km/h with short bursts almost twice that fast.']::text[], '/models/emperor-penguin.glb', null, null, 1.15, 30, 1, 1.15, '20 years', false, false, array['#f4c542', '#1b2733']::text[], '🐧', 'bird', 95),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000008', 'giant-panda', 'Giant Panda', 'Ailuropoda melanoleuca', 'Mammal', 'Temperate bamboo forest of central China', 'Asia', 'Vulnerable', 'Herbivore', 'A bear that eats like a herbivore, the giant panda spends up to fourteen hours a day stripping bamboo, which its gut digests poorly. Its black-and-white coat and its enlarged wrist bone, which works as a thumb, suit a carnivore turned full-time browser.', array['A panda eats 12 to 38 kg of bamboo every day to stay fed.', 'An enlarged wrist bone works as a sixth thumb for gripping bamboo stems.', 'Newborn cubs weigh about 100 grams, roughly a thousandth of their mother''s weight.', 'Despite their bulk, pandas climb trees well and often nap in the branches.']::text[], '/models/giant-panda.glb', null, '/sounds/giant-panda.ogg', 1.6, 110, 1.6, 0.85, '20-30 years', false, false, array['#f2f2f0', '#1c1c1e']::text[], '🐼', 'quadruped', 95),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000009', 'giraffe', 'Giraffe', 'Giraffa camelopardalis', 'Mammal', 'African savanna & open woodland', 'Africa', 'Vulnerable', 'Herbivore', 'The world''s tallest animal browses acacia crowns that no other herbivore can reach, using a prehensile 45-centimetre tongue to strip thorny leaves. Its long neck carries the same seven vertebrae as a human''s, each one enormously elongated.', array['A giraffe''s heart can weigh about 11 kg and pumps blood two metres up to the head.', 'The tongue is dark purple, which may protect it from sunburn while feeding.', 'No two giraffes share the same coat pattern, and each is stable for life.', 'Giraffes sleep very little, often in short bouts standing up.']::text[], '/models/giraffe.glb', null, null, 5.5, 1200, 4, 5.5, '20-25 years', false, false, array['#e0b25c', '#5a3a17']::text[], '🦒', 'quadruped', 92),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000010', 'gooty-tarantula', 'Gooty Tarantula', 'Poecilotheria metallica', 'Arachnid', 'Dry deciduous forest of Andhra Pradesh, India', 'Asia', 'Critically Endangered', 'Insectivore', 'This arboreal tarantula is the only spider known to wear a metallic blue coat, patterned with a geometric mark on the abdomen. It lives in holes in old trees within a tiny forest fragment in southern India, and its entire known range is smaller than the city of Paris.', array['Its electric blue colour is unique among tarantulas and fades to grey as the spider ages.', 'The species was named after Gooty, the Indian town near where it was first collected.', 'It shelters by day in tree holes and is active at night, leaping between branches.', 'Its known range covers well under 100 square kilometres of degraded forest.']::text[], '/models/gooty-tarantula.glb', null, null, 0.2, 0.04, 0.2, 0.05, '10-15 years', false, false, array['#2f6fd0', '#f0c14b']::text[], '🕷️', 'insect', 62),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000011', 'gray-wolf', 'Gray Wolf', 'Canis lupus', 'Mammal', 'Boreal forest, tundra & mountain ranges', 'Europe', 'Least Concern', 'Carnivore', 'The ancestor of every domestic dog, the gray wolf lives in family packs built around a breeding pair and their offspring. A single pack can patrol hundreds of square kilometres, shaping the movements of deer, elk and reindeer across the landscape.', array['A wolf pack is essentially a family, usually two parents and their young of several years.', 'A howl carries up to 10 km in open country and helps packs stay in contact.', 'Wolves routinely travel 30 km in a day and can cover far more when dispersing.', 'By culling weak prey, wolves keep herds healthier and reduce overgrazing.']::text[], '/models/gray-wolf.glb', null, '/sounds/gray-wolf.ogg', 1.5, 40, 1.5, 0.8, '6-8 years', false, false, array['#8d949c', '#2b3138']::text[], '🐺', 'quadruped', 89),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000012', 'great-white-shark', 'Great White Shark', 'Carcharodon carcharias', 'Fish', 'Temperate & subtropical coastal seas', 'Oceans', 'Vulnerable', 'Carnivore', 'The great white is a torpedo-shaped lamnid shark that hunts seals and large fish in cool coastal waters, sometimes launching its whole body clear of the surface. Pores on its snout detect the faint electrical fields of a hidden fish, and it keeps its muscles warmer than the surrounding sea.', array['Ampullae of Lorenzini on its snout sense electrical fields produced by living prey.', 'It is one of the few fish that is partially warm-blooded, holding heat in its swimming muscles.', 'Females grow larger than males and can exceed 5 metres in length.', 'Attacks on surfboards from below often follow a full breach, with the shark leaving the water entirely.']::text[], '/models/great-white-shark.glb', null, null, 5, 1100, 5, 1.2, '70 years', false, false, array['#8fa3ad', '#22303a']::text[], '🦈', 'marine', 96),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000013', 'green-anaconda', 'Green Anaconda', 'Eunectes murinus', 'Reptile', 'Amazon & Orinoco swamps and slow rivers', 'South America', 'Least Concern', 'Carnivore', 'The heaviest snake in the world, the green anaconda is an ambush hunter that waits in murky water with only its eyes and nostrils above the surface. It kills by constriction, coiling around prey such as caiman, capybara and deer before swallowing it whole.', array['Females are far larger than males and can weigh well over 100 kg.', 'Its eyes and nostrils sit on top of the head so it can breathe while almost fully submerged.', 'Unlike most snakes it gives birth to live young, sometimes dozens at once.', 'The name anaconda may derive from a Sinhalese word by way of Tamil, carried to South America by colonial-era writers.']::text[], '/models/green-anaconda.glb', null, null, 6, 70, 6, 0.3, '10-15 years', false, false, array['#4f8a3d', '#1f2a18']::text[], '🐍', 'serpent', 86),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000014', 'king-cobra', 'King Cobra', 'Ophiophagus hannah', 'Reptile', 'South & Southeast Asian forest and plantation', 'Asia', 'Vulnerable', 'Carnivore', 'The longest venomous snake in the world, the king cobra specialises in eating other snakes, including cobras and pythons. Unusually for a snake, the female builds a nest of leaf litter and guards her eggs until they hatch.', array['It can exceed 5 metres in length, making it the longest venomous snake alive.', 'Its scientific name, Ophiophagus, means snake-eater.', 'It can rear up a third of its body and advance on an intruder while holding that pose.', 'The female stays with her nest for weeks, the closest thing to parental care among snakes.']::text[], '/models/king-cobra.glb', null, null, 4, 6, 4, 0.3, '20 years', false, false, array['#b9a24b', '#23301f']::text[], '🐍', 'serpent', 87),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000015', 'lion', 'Lion', 'Panthera leo', 'Mammal', 'African savanna & grassland', 'Africa', 'Vulnerable', 'Carnivore', 'Lions are the only cats that live in permanent social groups, and a pride''s females do most of the hunting as a coordinated team. A male''s mane darkens with age and condition, advertising his fitness to rivals and mates alike.', array['A lion''s roar carries about 8 km across open savanna at night.', 'Pride females usually hunt together, fanning out to ambush herds from different sides.', 'Male lions can sleep for up to 20 hours a day between patrols.', 'Cubs are born with faint spots that fade as they grow.']::text[], '/models/lion.glb', null, '/sounds/lion.ogg', 2.5, 190, 2.5, 1.2, '10-14 years', false, false, array['#e8a33d', '#3d2410']::text[], '🦁', 'quadruped', 99),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000016', 'megalodon', 'Megalodon', 'Otodus megalodon', 'Fish', 'Warm Miocene & Pliocene seas worldwide', 'Oceans', 'Extinct', 'Carnivore', 'Megalodon was a shark that grew longer than a city bus, hunting whales and other large marine mammals in warm seas for over thirteen million years. It is known mostly from its enormous fossil teeth, which are common enough to wash up on beaches today.', array['Its triangular teeth reached about 18 cm in slant height, among the largest of any fish.', 'Estimated bite forces exceed those calculated for Tyrannosaurus rex.', 'Nursery areas in shallow coastal water have been identified from fossil juvenile teeth.', 'It disappeared around 3.6 million years ago as oceans cooled and its prey shifted poleward.']::text[], '/models/megalodon.glb', null, null, 16, 50000, 16, 3.5, 'Unknown', true, true, array['#c8b48a', '#2b2118']::text[], '🦷', 'marine', 93),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000017', 'monarch-butterfly', 'Monarch Butterfly', 'Danaus plexippus', 'Insect', 'Milkweed meadows & overwintering groves', 'North America', 'Endangered', 'Herbivore', 'Each autumn monarchs east of the Rockies stream up to 4,800 km to a handful of mountain forests in central Mexico, roosting in such dense clusters that branches bend under their weight. Caterpillars eat only milkweed, storing its toxins to make themselves poisonous to birds.', array['The orange wings warn predators of toxins absorbed from milkweed as a caterpillar.', 'No single butterfly makes the round trip: the return north takes three or four generations.', 'Overwintering colonies in Mexico can contain tens of millions of individuals.', 'A tagged monarch has been recorded flying nearly 4,800 km from Canada to Mexico.']::text[], '/models/monarch-butterfly.glb', null, null, 0.1, 0.0005, 0.1, 0.03, '2-6 weeks, 8-9 months for the migratory generation', false, false, array['#f08a1d', '#241a2e']::text[], '🦋', 'insect', 93),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000018', 'red-kangaroo', 'Red Kangaroo', 'Osphranter rufus', 'Mammal', 'Australian arid outback & scrubland', 'Oceania', 'Least Concern', 'Herbivore', 'The largest living marsupial hops across the Australian interior on powerful hind legs, using its thick tail as a counterbalance and a fifth limb at slow speeds. Females can pause the development of an embryo until the previous joey leaves the pouch.', array['A red kangaroo can hop at around 60 km/h in short bursts.', 'A newborn joey is barely 2 cm long and crawls unaided into the pouch.', 'Males are rusty red while females are often blue-grey, once mistaken for a separate species.', 'Kangaroos cannot easily move backwards, which is why they appear on Australia''s coat of arms.']::text[], '/models/red-kangaroo.glb', null, null, 1.6, 85, 1.5, 1.6, '8-12 years', false, false, array['#c96a3a', '#4a2f1c']::text[], '🦘', 'biped', 91),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000019', 'saltwater-crocodile', 'Saltwater Crocodile', 'Crocodylus porosus', 'Reptile', 'Mangroves, estuaries & coastal rivers', 'Oceania', 'Least Concern', 'Carnivore', 'The largest living reptile patrols mangroves and estuaries from eastern India to northern Australia, ambushing prey at the water''s edge with a bite measured as the strongest of any living animal. It tolerates salt water well enough to cross open ocean between islands.', array['Large males can exceed 6 metres and weigh over 1,000 kg.', 'Its bite has been measured as the most powerful of any living animal.', 'It can launch its body almost completely out of the water to seize prey above the surface.', 'Salt glands on the tongue let it survive for weeks in full-strength seawater.']::text[], '/models/saltwater-crocodile.glb', null, null, 5, 500, 5, 0.6, '60-70 years', false, false, array['#6f7f4a', '#2a2f1e']::text[], '🐊', 'quadruped', 84),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000020', 'smilodon', 'Smilodon', 'Smilodon fatalis', 'Mammal', 'Pleistocene grassland & woodland of the Americas', 'North America', 'Extinct', 'Carnivore', 'Smilodon, the saber-toothed cat, ambushed large Pleistocene herbivores with canine teeth nearly 30 cm long. Its stocky body and powerful forelimbs were built for wrestling prey to the ground rather than for long chases.', array['Its upper canines could reach about 28 cm, including the root.', 'Smilodon had unusually robust forelimbs, useful for pinning struggling prey.', 'Thousands of Smilodon fatalis fossils have been recovered from the La Brea Tar Pits in Los Angeles.', 'It died out roughly 10,000 years ago, along with much of the Pleistocene megafauna.']::text[], '/models/smilodon.glb', null, null, 1.2, 280, 2.1, 1.2, 'Unknown', true, true, array['#c9a06a', '#43301f']::text[], '🦴', 'quadruped', 82),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000021', 'toco-toucan', 'Toco Toucan', 'Ramphastos toco', 'Bird', 'South American savanna, forest edge & palm groves', 'South America', 'Least Concern', 'Omnivore', 'The toco toucan carries the largest bill of any toucan, a hollow 20-centimetre structure that looks heavy but weighs less than its feathers. It plucks fruit at the end of thin branches and tosses each item into the air before catching and swallowing it.', array['Its bill is mostly air-filled keratin, so it is far lighter than it looks.', 'Blood vessels in the bill shed heat, making it an important radiator in the tropics.', 'It sleeps with the bill resting along its back and the tail folded over it.', 'Toucans nest in tree cavities and are important seed dispersers in the Cerrado and Amazon.']::text[], '/models/toco-toucan.glb', null, '/sounds/toco-toucan.ogg', 0.6, 0.7, 0.6, 0.35, '20 years', false, false, array['#f26b21', '#1b1b1f']::text[], '🦜', 'bird', 85),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000022', 'tyrannosaurus-rex', 'Tyrannosaurus rex', 'Tyrannosaurus rex', 'Reptile', 'Late Cretaceous floodplains & forests', 'North America', 'Extinct', 'Carnivore', 'Tyrannosaurus rex was a 12-metre predator of the Late Cretaceous, with a skull built to deliver one of the most powerful bites of any land animal. Its arms were famously short, yet each was strong enough to hold struggling prey close.', array['Its bite force is estimated among the highest of any land animal that has ever lived.', 'Around 60 teeth lined its jaws, some over 30 cm long including the root.', 'Its arms were short but heavily muscled, with two clawed fingers on each hand.', 'It lived between about 68 and 66 million years ago, at the very end of the dinosaur era.']::text[], '/models/tyrannosaurus-rex.glb', null, null, 12.3, 8000, 12.3, 4, 'Unknown', true, true, array['#6b8f3e', '#2a2418']::text[], '🦖', 'theropod', 97),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000023', 'weddell-seal', 'Weddell Seal', 'Leptonychotes weddellii', 'Mammal', 'Fast ice & coastal waters around Antarctica', 'Antarctica', 'Least Concern', 'Piscivore', 'The Weddell seal lives further south than any other mammal, hauling out on the fast ice around Antarctica and slipping into the water through holes it keeps open with its teeth. It dives deeper and longer than almost any other seal, hunting fish beneath metres of ice.', array['It can dive deeper than 600 metres and stay submerged for over an hour.', 'Seals rasp their breathing holes open with their teeth, which wear down over a lifetime.', 'Weddell seals are the most southerly breeding mammal on Earth.', 'Pups are born on the ice in spring and can swim within days.']::text[], '/models/weddell-seal.glb', null, null, 3, 450, 3, 0.6, '20-25 years', false, false, array['#a8b6bd', '#33414d']::text[], '🦭', 'marine', 76),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000024', 'woolly-mammoth', 'Woolly Mammoth', 'Mammuthus primigenius', 'Mammal', 'Ice Age mammoth steppe of Eurasia', 'Europe', 'Extinct', 'Herbivore', 'The woolly mammoth roamed the cold grasslands of Ice Age Eurasia, wrapped in a dense coat of guard hairs and wool with a layer of fat beneath. Curved tusks up to four metres long were used to sweep snow aside in search of frozen grass.', array['Its tusks could grow to about 4 metres and are among the largest of any elephant relative.', 'Small ears and a short tail limited heat loss in the freezing steppe climate.', 'Whole carcasses with skin and hair intact have been recovered from Siberian permafrost.', 'A dwarfed population survived on Wrangel Island until roughly 4,000 years ago.']::text[], '/models/woolly-mammoth.glb', null, null, 3.4, 6000, 5, 3.4, '60-80 years', true, true, array['#a9744f', '#4a3524']::text[], '🦣', 'quadruped', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000025', 'polar-bear', 'Polar Bear', 'Ursus maritimus', 'Mammal', 'Arctic sea ice, coastlines & tundra', 'North America', 'Vulnerable', 'Carnivore', 'The polar bear is a sea-ice hunter that spends most of its life on frozen ocean, moving between floes to ambush ringed and bearded seals at their breathing holes. Its fur carries no white pigment, its skin underneath is black, and a thick layer of blubber lets it swim for hours in water close to freezing.', array['Its fur is transparent rather than white; the hairs scatter light, and the skin beneath is black.', 'A polar bear can swim for days at a time, paddling with its wide front paws.', 'Pregnant females dig dens in snowdrifts and fast for months while nursing their cubs.', 'It is classed as a marine mammal, and its main prey is seal rather than fish.']::text[], null, null, null, 2.4, 450, 2.4, 1.4, '25-30 years', false, false, array['#eef1f2', '#3b4c58']::text[], '🐻‍❄️', 'quadruped', 93),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000026', 'snow-leopard', 'Snow Leopard', 'Panthera uncia', 'Mammal', 'High mountains of Central Asia', 'Asia', 'Vulnerable', 'Carnivore', 'The snow leopard lives above the tree line in the mountains of Central Asia, stalking ibex and blue sheep across cliffs and scree. Its long tail works as a counterweight on steep ground, and its paws are furred underneath for grip on snow.', array['The tail can be almost as long as the body and is thick with fat and fur.', 'Snow leopards cannot roar; they chuff, mew and purr.', 'Each cat''s rosette pattern is unique, which is how camera traps tell individuals apart.', 'Its fur grows up to 12 cm long on the back in winter.']::text[], null, null, null, 1.1, 45, 1.1, 0.56, '15-18 years', false, false, array['#e8e4d9', '#5c6470']::text[], '🐆', 'quadruped', 82),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000027', 'cheetah', 'Cheetah', 'Acinonyx jubatus', 'Mammal', 'African savanna & dry grassland', 'Africa', 'Vulnerable', 'Carnivore', 'The cheetah is the fastest land animal over short distances, reaching about 100 km/h in a sprint that lasts a few hundred metres. It has a slim, deep-chested build, claws that stay out like running studs, and a long tail that swings out to steer through a turn.', array['Every cheetah has its own spot pattern, and a black tear-stripe runs from each eye to the mouth.', 'It can accelerate from a standstill to highway speed in about three seconds.', 'A hunt usually ends inside 20 seconds, after which the cat must rest.', 'Brothers often form coalitions that hold a territory together for years.']::text[], null, null, null, 1.3, 50, 1.3, 0.8, '10-15 years', false, false, array['#e3b45c', '#2f2a24']::text[], '🐆', 'quadruped', 92),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000028', 'amur-leopard', 'Amur Leopard', 'Panthera pardus orientalis', 'Mammal', 'Temperate forest of the Russian Far East & northeast China', 'Asia', 'Critically Endangered', 'Carnivore', 'The Amur leopard is the northernmost leopard, living in mixed forest where winter temperatures fall far below freezing. Its coat grows long and pale in winter, and its rosettes are widely spaced with thick, unbroken rings. The wild population fell to a few dozen animals before camera-trap surveys and a protected national park began to turn the decline around.', array['Camera-trap surveys along the Russian-Chinese border counted 92 individuals between 2014 and 2015.', 'It is the only leopard subspecies adapted to a cold, snowy climate.', 'A captive breeding programme was started in 1961 from nine wild-born founders.', 'Its range overlaps with that of the Amur tiger, which takes larger prey.']::text[], null, null, null, 1.8, 40, 1.8, 0.7, '10-12 years', false, false, array['#e0cfae', '#26241f']::text[], '🐆', 'quadruped', 68),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000029', 'spotted-hyena', 'Spotted Hyena', 'Crocuta crocuta', 'Mammal', 'African savanna, woodland & desert edge', 'Africa', 'Least Concern', 'Carnivore', 'The spotted hyena lives in clans of up to eighty animals in which females are larger and outrank the males. It hunts most of what it eats, and its jaws can crack the leg bones of a giraffe, so a clan can finish a carcass that lions have left.', array['The clan is led by females, who feed first at every kill.', 'Its whooping laugh carries for kilometres and signals age and social rank, not amusement.', 'Hyenas digest bone, hide and horn, and their droppings are white with calcium.', 'Cubs are born with their eyes open and with teeth already through.']::text[], null, null, null, 1.3, 60, 1.3, 0.8, '12-20 years', false, false, array['#c9b28b', '#3a3227']::text[], '🐕', 'quadruped', 78),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000030', 'wolverine', 'Wolverine', 'Gulo gulo', 'Mammal', 'Boreal forest, tundra & alpine scrub', 'North America', 'Least Concern', 'Carnivore', 'The wolverine is the largest land-dwelling mustelid, a stocky animal built for snow and long distances rather than speed. It patrols a vast home range alone, scavenging carcasses and killing prey in deep drifts, and its wide, furred paws spread its weight on top of the snow.', array['Males are about a third heavier than females and may hold ranges of several hundred square kilometres.', 'It can chew through frozen carrion that other predators abandon.', 'A strong-smelling secretion is used to mark food caches and territory.', 'It dens in deep snow, and cubs stay with the female for about a year.']::text[], null, null, null, 0.85, 15, 0.85, 0.4, '5-7 years', false, false, array['#6b5b4a', '#1f1c19']::text[], '🦡', 'quadruped', 74),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000031', 'mountain-gorilla', 'Mountain Gorilla', 'Gorilla beringei beringei', 'Mammal', 'Albertine Rift montane cloud forest', 'Africa', 'Endangered', 'Herbivore', 'Mountain gorillas live in family groups led by a silverback, in the cold cloud forest of the Virunga volcanoes and the Bwindi forest. They spend most of the day eating leaves, shoots and bamboo, and each animal builds a fresh nest of vegetation to sleep in. Numbers fell to a few hundred in the twentieth century and now stand at just over a thousand.', array['A silverback''s back turns grey with age, and he decides where the group feeds and sleeps.', 'The mountain gorilla is one of the few great apes whose numbers are rising.', 'Groups range between 2,200 and 4,300 metres up, where nights are often frosty.', 'Adult males eat around 19 kg of vegetation a day.']::text[], null, null, null, 1.7, 155, 1.5, 1.7, '40-50 years', false, false, array['#4a4a48', '#151515']::text[], '🦍', 'biped', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000032', 'bornean-orangutan', 'Bornean Orangutan', 'Pongo pygmaeus', 'Mammal', 'Lowland & swamp forest of Borneo', 'Asia', 'Critically Endangered', 'Omnivore', 'The Bornean orangutan is the largest animal that lives mainly in trees, spending its life in the canopy of lowland and swamp forest. Adults are largely solitary, and a male''s long call carries through the trees to advertise his presence. Females give birth roughly once every six to eight years, the slowest rate of any land mammal.', array['Males weigh about twice as much as females and grow wide cheek pads called flanges.', 'It builds a new nest of branches in the trees almost every night.', 'Fruit makes up most of the diet, and lean seasons are spent on bark and leaves.', 'It has been recorded using leaves as umbrellas and as gloves against thorny fruit.']::text[], null, null, null, 1.4, 75, 1.4, 1.2, '35-45 years', false, false, array['#b8622b', '#2c1a10']::text[], '🦧', 'biped', 80),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000033', 'chimpanzee', 'Chimpanzee', 'Pan troglodytes', 'Mammal', 'Equatorial African forest & savanna woodland', 'Africa', 'Endangered', 'Omnivore', 'Chimpanzees live in communities of up to 200 animals that split into small parties to forage by day. They eat fruit, leaves, insects and meat, and they are among the few animals that make and use tools, fishing termites out of mounds with stripped twigs. Males usually stay in their birth community while females move away.', array['Each community has its own set of tool-using and grooming traditions.', 'Chimpanzees hunt monkeys cooperatively and share the meat.', 'They build a fresh nest of leaves and branches in the trees every night.', 'A chimpanzee can recognise itself in a mirror.']::text[], null, null, null, 1.5, 40, 0.9, 1.5, '40-60 years', false, false, array['#3b3129', '#161310']::text[], '🐵', 'biped', 89),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000034', 'hippopotamus', 'Hippopotamus', 'Hippopotamus amphibius', 'Mammal', 'Rivers, lakes & wetlands of sub-Saharan Africa', 'Africa', 'Vulnerable', 'Herbivore', 'The hippopotamus stands or floats in shallow water through the day and comes ashore at dusk to graze on grass, walking several kilometres from the river. Its skin secretes a reddish fluid often called blood sweat, which acts as a sunscreen and an antibiotic. Despite its bulk it can outrun a human on land.', array['A hippo can hold its breath for about five minutes and closes its ears and nostrils underwater.', 'Its closest living relatives are whales and dolphins, not pigs.', 'Males fight over stretches of water with lower canines that never stop growing.', 'Calves are born underwater and must surface to take their first breath.']::text[], null, null, null, 4, 1500, 4, 1.5, '45-55 years', false, false, array['#8a7f74', '#3a2f2a']::text[], '🦛', 'quadruped', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000035', 'white-rhinoceros', 'White Rhinoceros', 'Ceratotherium simum', 'Mammal', 'African grassland & savanna', 'Africa', 'Near Threatened', 'Herbivore', 'The white rhinoceros is the largest living rhino and a pure grazer, cropping short grass with a wide, square lip. It carries two horns made of keratin, the same protein as hair and fingernails. The name has nothing to do with colour: it is usually traced to the Dutch word wijd, describing the width of its mouth.', array['The southern subspecies recovered from fewer than a hundred animals to more than fifteen thousand.', 'The northern white rhinoceros survives only as two females and frozen embryos.', 'A rhino horn is not bone, and it regrows if it is cut cleanly.', 'White rhinos are the most social rhinos and often graze in small groups.']::text[], null, null, null, 3.7, 2000, 3.7, 1.8, '40-50 years', false, false, array['#b8b2a6', '#40403c']::text[], '🦏', 'quadruped', 87),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000036', 'plains-zebra', 'Plains Zebra', 'Equus quagga', 'Mammal', 'East & southern African savanna grassland', 'Africa', 'Near Threatened', 'Herbivore', 'The plains zebra is the most widespread of the three zebra species, moving in herds that follow the rains across East and southern African grassland. Each animal''s stripe pattern is unique, and a foal learns its mother''s pattern within days of birth. Its teeth crop grass so short that wildebeest and gazelle can graze behind the herd.', array['The stripes may confuse biting flies, which land less often on patterned surfaces.', 'A zebra''s coat is black with white stripes, not white with black.', 'The quagga, a zebra striped only on the front half, was hunted to extinction by 1883.', 'Herd members take turns to sleep while others stand watch.']::text[], null, null, null, 2.3, 250, 2.3, 1.35, '20-25 years', false, false, array['#e8e6e1', '#2b2b2b']::text[], '🦓', 'quadruped', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000037', 'american-bison', 'American Bison', 'Bison bison', 'Mammal', 'North American prairie & river valley', 'North America', 'Near Threatened', 'Herbivore', 'The American bison is the heaviest land animal in North America, a grazer of the prairies that once numbered in the tens of millions. Hunting reduced the herds to a few hundred animals in the nineteenth century, and every bison alive today descends from those survivors. Bulls carry a heavy shoulder hump and can push through deep snow to reach grass.', array['Bison wallow in shallow dust bowls to shed insects and rub off winter hair.', 'They can run at around 55 km/h despite weighing close to a tonne.', 'The species was reduced to as few as 541 animals before protection began.', 'The hump is muscle, anchored to long spines on the shoulder vertebrae.']::text[], null, null, null, 3, 730, 3, 1.75, '15-20 years', false, false, array['#6b4a31', '#241a12']::text[], '🦬', 'quadruped', 79),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000038', 'moose', 'Moose', 'Alces alces', 'Mammal', 'Northern boreal forest & wetland', 'North America', 'Least Concern', 'Herbivore', 'The moose is the largest deer, a browser of willow, birch and water plants that wades into lakes to feed. Bulls grow broad palmate antlers each spring and drop them in winter, and both sexes carry a flap of skin and hair under the chin called a bell. Long legs let it wade through deep snow and step over fallen timber.', array['An adult moose can eat around 30 kg of browse a day in summer.', 'Its antlers can span 1.8 metres and are regrown from scratch every year.', 'It can close its nostrils and browse underwater.', 'The shoulder hump stores fat and anchors the neck muscles.']::text[], null, null, null, 2.8, 500, 2.8, 1.9, '15-25 years', false, false, array['#4a3a2c', '#1a1512']::text[], '🫎', 'quadruped', 84),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000039', 'reindeer', 'Reindeer', 'Rangifer tarandus', 'Mammal', 'Arctic tundra, boreal forest & mountain plateau', 'Europe', 'Vulnerable', 'Herbivore', 'The reindeer, called caribou in North America, is the only deer in which females also grow antlers, keeping them through the winter to defend the craters they dig for lichen. Herds migrate hundreds of kilometres between tundra summer range and forest winter range. A coat of hollow hairs and wide hooves carry it over snow and bog.', array['Reindeer eyes change colour with the season, from gold in summer to blue in winter.', 'They can see ultraviolet light, which makes urine trails and fur stand out in snow.', 'Bulls shed their antlers in early winter while cows keep theirs until spring.', 'The Svalbard subspecies is short-legged and small, an effect of island isolation.']::text[], null, null, null, 2, 120, 2, 1.2, '10-15 years', false, false, array['#8a7861', '#33291f']::text[], '🦌', 'quadruped', 86),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000040', 'giant-anteater', 'Giant Anteater', 'Myrmecophaga tridactyla', 'Mammal', 'Grassland, savanna & forest of Central & South America', 'South America', 'Vulnerable', 'Insectivore', 'The giant anteater walks on its knuckles to protect the long claws it uses to open termite mounds, and it feeds by flicking a sticky tongue up to 45 cm long into the tunnel around 150 times a minute. It has no teeth at all, crushing insects against the roof of its mouth instead. An animal may visit dozens of mounds in a day and rarely destroys one.', array['The tongue is anchored to the sternum and can only move in and out, not side to side.', 'A pup rides on its mother''s back for months, its coat matching hers.', 'It sleeps with its bushy tail wrapped over its body for warmth.', 'When cornered it rears up on its hind legs and slashes with its foreclaws.']::text[], null, null, null, 2, 40, 2, 0.6, '25 years (captivity)', false, false, array['#57514a', '#241f1a']::text[], '🐜', 'quadruped', 72),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000041', 'three-toed-sloth', 'Three-toed Sloth', 'Bradypus variegatus', 'Mammal', 'Tropical rainforest canopy of Central & South America', 'South America', 'Least Concern', 'Herbivore', 'The three-toed sloth hangs in the canopy of Central and South American forests and moves so slowly that algae grow in the grooves of its fur and tint it green. It comes down to the ground about once a week to defecate, and it sleeps 14 to 16 hours a day. Long arms and curved claws make it a capable swimmer and a helpless walker.', array['Green algae living in the fur help camouflage the animal among leaves.', 'Its body temperature drops several degrees at night.', 'A sloth''s stomach can take over a week to process a single meal.', 'It swims well and crosses rivers faster than it can walk.']::text[], null, null, null, 0.6, 4.3, 0.6, 0.3, '30-40 years', false, false, array['#8f8a6b', '#2e2c22']::text[], '🦥', 'quadruped', 85),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000042', 'meerkat', 'Meerkat', 'Suricata suricatta', 'Mammal', 'Kalahari & Namib semi-desert scrub', 'Africa', 'Least Concern', 'Insectivore', 'Meerkats live in packs of up to thirty animals that share a burrow system and take turns on sentry duty. One stands upright on a mound while the others dig for insects and scorpions, and the whole pack helps raise the pups of the dominant female. Pups are given live prey in stages so they can learn to handle it.', array['A burrow system can have around fifteen entrances and two or three levels of tunnel.', 'Meerkats tolerate scorpion venom well and eat the sting first.', 'Babysitters stay at the burrow while the rest of the pack forages.', 'A sentry uses different alarm calls for snakes, raptors and jackals.']::text[], null, null, null, 0.3, 0.8, 0.3, 0.3, '5-15 years', false, false, array['#c8a86a', '#3d3122']::text[], '🐿️', 'biped', 83),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000043', 'red-fox', 'Red Fox', 'Vulpes vulpes', 'Mammal', 'Woodland, farmland & the edges of towns', 'Europe', 'Least Concern', 'Omnivore', 'The red fox is the most widespread wild carnivore, native across Europe and Asia and introduced to North America and Australia. It hunts alone at dusk and dawn, pouncing on small mammals it hears moving under snow or long grass. The bushy tail, called a brush, is used for balance, warmth and signalling.', array['It can hear a mouse moving under deep snow and pounces with its forepaws together.', 'Surplus food is cached under leaves and snow and dug up later.', 'Cubs are born blind and stay in the den for about a month.', 'Urban foxes den under sheds and cross roads mainly at night.']::text[], null, null, null, 0.7, 6, 0.7, 0.4, '3-12 years', false, false, array['#c85f27', '#2b1c12']::text[], '🦊', 'quadruped', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000044', 'arctic-fox', 'Arctic Fox', 'Vulpes lagopus', 'Mammal', 'Arctic tundra & sea ice', 'North America', 'Least Concern', 'Carnivore', 'The arctic fox lives on tundra and sea ice around the Arctic, hunting lemmings and scavenging the remains of polar bear kills. Its winter coat is white in most populations and blue-grey in coastal ones, and its rounded ears and short muzzle keep heat loss to a minimum.', array['It does not begin to shiver until roughly -70 °C, the best insulation recorded in a mammal.', 'It caches food in the ground during autumn for the lean winter months.', 'The blue morph is common near the coast, where snow cover is less reliable.', 'Arctic foxes trail polar bears to take scraps from their kills.']::text[], null, null, null, 0.55, 3.5, 0.55, 0.28, 'Up to 11 years', false, false, array['#f2f4f6', '#4a5a6a']::text[], '🦊', 'quadruped', 76),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000045', 'humpback-whale', 'Humpback Whale', 'Megaptera novaeangliae', 'Mammal', 'Open ocean; feeds in cold polar seas and breeds in warm coastal waters', 'Oceans', 'Least Concern', 'Filter Feeder', 'The humpback is a baleen whale built for long migrations, feeding on krill and schooling fish in cold water each summer and travelling thousands of kilometres to warm, shallow breeding grounds in winter. Its pectoral fins are the longest of any whale, about a third of its body length, and it herds prey with spirals of exhaled bubbles. Adults run 14 to 15 metres, and females grow slightly longer than males.', array['Its genus name Megaptera means "great wing", after pectoral fins that can be five metres long.', 'Males sing long, structured songs that change over the years and spread from population to population.', 'A humpback''s tail flukes can be 5.5 metres wide and are serrated along the trailing edge.', 'It may live for over 50 years, and the oldest known individual was 95.']::text[], null, null, null, 16, 30000, 16, 3.5, '50-95 years', false, false, array['#5d7f9e', '#16283a']::text[], '🐋', 'whale', 92),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000046', 'sperm-whale', 'Sperm Whale', 'Physeter macrocephalus', 'Mammal', 'Deep ocean; hunts squid far below the surface in all seas', 'Oceans', 'Vulnerable', 'Carnivore', 'The sperm whale is the largest toothed predator, its block-shaped head making up as much as a third of its length and carrying the biggest brain of any animal alive. It hunts squid in near-total darkness, diving to about 2,250 metres and surfacing to breathe for roughly eight minutes between plunges. Females and calves travel together in warm water while adult males range toward the poles.', array['Mature males average 16 metres and about 45 tonnes; females average 11 metres and 15 tonnes.', 'At 2,250 metres it is the third deepest-diving mammal, after the southern elephant seal and Cuvier''s beaked whale.', 'Sperm whales can live 70 years or more and often carry scars from the squid they fight.', 'Ambergris, a waxy material from the digestive tract, is still collected as a perfume fixative.']::text[], null, null, null, 16, 45000, 16, 4, '70 years or more', false, false, array['#7a7d84', '#1b1e23']::text[], '🐳', 'whale', 85),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000047', 'orca', 'Orca', 'Orcinus orca', 'Mammal', 'All oceans, from polar pack ice to tropical seas', 'Oceans', 'Data Deficient', 'Carnivore', 'The orca, or killer whale, is the largest member of the dolphin family, marked by a tall dorsal fin and a black-and-white pattern that differs between populations. Pods hunt cooperatively, and their diets vary sharply: some groups take fish such as salmon, others hunt seals, dolphins and even large whales. Females live far longer than males and stop breeding decades before they die.', array['Males typically measure 6 to 8 metres and weigh over 6 tonnes; females run 5 to 7 metres and 3 to 4 tonnes.', 'Wild females average 50 to 80 years, while males average around 30.', 'Fish-eating and mammal-hunting groups differ in diet, calls and social structure, and rarely mix.', 'Orcas are one of the few animals that go through menopause and live on for decades afterwards.']::text[], null, null, null, 7.5, 6000, 7.5, 2, '30-80 years', false, false, array['#414b57', '#0e1218']::text[], '🐋', 'whale', 94),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000048', 'bottlenose-dolphin', 'Bottlenose Dolphin', 'Tursiops truncatus', 'Mammal', 'Coastal and offshore waters of warm and temperate seas', 'Oceans', 'Least Concern', 'Piscivore', 'The common bottlenose dolphin is the dolphin most people picture: grey, robust, and equally at home in estuaries, harbours and open ocean. It finds fish and squid by echolocation, often in coordinated groups, and each individual carries a signature whistle that others use like a name. Adults are usually 2.5 to 3.5 metres long and weigh 200 to 500 kilograms.', array['Dolphins can recognise the signature whistles of former companions after more than 20 years apart.', 'They eat 10 to 20 percent of their body weight each day, more when nursing a calf.', 'The average lifespan is at least 40 years and can reach 60, with females usually outliving males.', 'Inshore and offshore populations differ in size, diet and how far they travel.']::text[], null, null, null, 3, 300, 3, 0.8, '40-60 years', false, false, array['#7fa6c4', '#1d3648']::text[], '🐬', 'whale', 93),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000049', 'narwhal', 'Narwhal', 'Monodon monoceros', 'Mammal', 'High Arctic fjords and pack ice of Canada, Greenland and Russia', 'Oceans', 'Least Concern', 'Carnivore', 'The narwhal is an Arctic whale with a mottled grey hide and, in males, a spiralled tusk that is really an overgrown left canine and can reach three metres. It winters among dense pack ice, breathing through leads and diving to depths of 2,370 metres for Greenland halibut, squid and shrimp. Its closest living relative is the beluga, with which it occasionally hybridises.', array['Adults measure 3.0 to 5.5 metres and weigh 800 to 1,600 kilograms.', 'The tusk is packed with millions of nerve endings and appears to sense temperature and salinity.', 'Age estimates from the eye lens suggest some females live past 100 years.', 'Most narwhals return to the same ice-free summering grounds year after year.']::text[], null, null, null, 4.5, 1200, 4.5, 1.2, '50-115 years', false, false, array['#a7b8c6', '#2b3a46']::text[], '🐋', 'whale', 82),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000050', 'walrus', 'Walrus', 'Odobenus rosmarus', 'Mammal', 'Arctic sea ice over shallow continental shelves', 'Oceans', 'Vulnerable', 'Carnivore', 'The walrus is a heavy Arctic pinniped with a whiskered muzzle and tusks in both sexes, exceeded in size among seals only by the elephant seals. It finds clams and other shellfish on shallow seabeds by feel, sweeping the bottom with sensitive whiskers and jets of water. Tusks are used to haul out onto ice and in fights, not to dig for food.', array['Pacific males can top 2,000 kilograms, though most adults weigh 800 to 1,700.', 'Both sexes carry tusks, which can reach a metre and weigh up to 5.4 kilograms each.', 'Walruses live about 20 to 30 years in the wild and feed mostly in water under 100 metres deep.', 'They can dive past 500 metres, but usually work the shallow shelf near the ice edge.']::text[], null, null, null, 3, 1200, 3, 1.1, '20-30 years', false, false, array['#b0906c', '#3b2a1f']::text[], '🦭', 'marine', 84),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000051', 'leopard-seal', 'Leopard Seal', 'Hydrurga leptonyx', 'Mammal', 'Antarctic pack ice and subantarctic islands', 'Antarctica', 'Least Concern', 'Carnivore', 'The leopard seal is the only large seal that regularly takes warm-blooded prey, hunting penguins and other seals as well as krill and fish. Females grow up to half again as large as males, and adults run 2.4 to 3.5 metres, with a long body, a reptilian-looking head and a wide gape. They keep to the pack ice for most of the year and wander north to subantarctic islands in winter.', array['Females can be up to 50 percent larger than males, an unusual gap for a carnivore.', 'Despite its reputation, krill and fish make up a large part of its diet by volume.', 'Wild leopard seals can live up to 26 years.', 'Males produce loud calls of 153 to 177 decibels and call for hours at a time.']::text[], null, null, null, 3, 400, 3, 0.8, 'up to 26 years', false, false, array['#9099a3', '#232a31']::text[], '🦭', 'marine', 70),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000052', 'sea-otter', 'Sea Otter', 'Enhydra lutris', 'Mammal', 'Kelp beds and shallow coastal waters of the North Pacific', 'North America', 'Endangered', 'Carnivore', 'The sea otter is the heaviest member of the weasel family and the only one that lives almost entirely in the sea, feeding on urchins, clams and crabs in kelp forests. It has no blubber, relying instead on the densest fur of any mammal and a very high metabolism that keeps it warm and hungry. Recovery from the fur trade has been uneven: some populations rebuilt, others remain small.', array['Its fur runs to about 130,000 hairs per square centimetre, roughly twice as dense as a northern fur seal''s.', 'Males weigh 22 to 45 kilograms and measure 1.2 to 1.5 metres, with females smaller.', 'Males typically live 10 to 15 years and females 15 to 20, with a recorded maximum of 23.', 'Otters rest wrapped in strands of kelp so they do not drift while sleeping.']::text[], null, null, null, 1.4, 30, 1.4, 0.3, '10-20 years', false, false, array['#7d5f47', '#241a13']::text[], '🦦', 'marine', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000053', 'california-sea-lion', 'California Sea Lion', 'Zalophus californianus', 'Mammal', 'Pacific coastlines, islands and docks from Canada to Mexico', 'North America', 'Least Concern', 'Piscivore', 'The California sea lion is the trained seal of aquaria and the loudest animal on many a harbour dock, an eared seal that swims with large foreflippers and walks on land on all fours. Males are much heavier than females and hold breeding territories on island rookeries through the summer. The population is large and still growing, and the species is listed as Least Concern.', array['Adult males reach 2.5 to 2.7 metres and about 350 kilograms; females are around 2.1 metres and 100 kilograms.', 'NOAA Fisheries gives their lifespan as 20 to 30 years, and one captive male reached 31.', 'Eared seals like this one have visible ear flaps and steer with the hind flippers, unlike true seals.', 'Bulls fast for weeks at a time while holding a territory on the rookery.']::text[], null, null, null, 2.5, 300, 2.5, 0.9, '20-30 years', false, false, array['#a9855c', '#33261a']::text[], '🦭', 'marine', 78),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000054', 'west-indian-manatee', 'West Indian Manatee', 'Trichechus manatus', 'Mammal', 'Rivers, estuaries and warm coastal shallows of the Atlantic', 'North America', 'Vulnerable', 'Herbivore', 'The West Indian manatee is a large, slow sirenian that grazes seagrass and river plants for hours at a time and rests just below the surface between meals. It cannot tolerate water below about 20 degrees for long, so Florida animals gather at warm springs and power plant outfalls each winter. Boat strikes remain a leading cause of death, and the species is listed as Vulnerable.', array['Adults are about 2.7 to 3.5 metres long and weigh 200 to 600 kilograms, with females the larger sex.', 'Manatees have a conveyor of teeth: new molars form at the back as worn ones drop out at the front.', 'They graze four to eight hours a day, eating 5 to 10 percent of their body weight in plants.', 'Manatees are estimated to live 50 years or more in the wild.']::text[], null, null, null, 3.5, 500, 3.5, 1, '50 years or more', false, false, array['#8c99a1', '#27333a']::text[], '🦭', 'marine', 80),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000055', 'giant-otter', 'Giant Otter', 'Pteronura brasiliensis', 'Mammal', 'Amazon, Orinoco and Pantanal rivers, creeks and oxbow lakes', 'South America', 'Endangered', 'Piscivore', 'The giant otter is the longest member of the weasel family, a noisy, social hunter of South American rivers that lives in family groups built around a breeding pair. It takes mostly fish, hunting in packs and eating several kilograms a day, and marks its territory with latrines and loud choruses of calls. Hunted for its pelt until the 1970s, it now survives in fragmented populations, mainly in Brazil and Peru.', array['Males measure 1.5 to 1.7 metres and females 1.0 to 1.5 metres, with the tail adding up to 70 centimetres more.', 'Males weigh 26 to 32 kilograms and females 22 to 26.', 'The longest documented wild lifespan is eight years; animals in captivity have reached 17.', 'Every giant otter has a unique pattern of white markings on its throat, used to tell individuals apart.']::text[], null, null, null, 1.7, 29, 1.7, 0.3, '8-17 years', false, false, array['#6d4b34', '#1e1410']::text[], '🦦', 'quadruped', 66),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000056', 'capybara', 'Capybara', 'Hydrochoerus hydrochaeris', 'Mammal', 'Amazonian wetlands, flooded savanna and riverbanks', 'South America', 'Least Concern', 'Herbivore', 'The capybara is the largest living rodent, a barrel-shaped grazer of rivers, marshes and flooded grassland across South America. It eats grasses and aquatic plants, has partly webbed feet, and escapes predators by diving, with eyes, ears and nostrils set high on the skull. Groups are dominated by one male and can hold twenty animals or more.', array['Adults grow to 106 to 134 centimetres in length, stand 50 to 62 centimetres at the shoulder and weigh 35 to 66 kilograms.', 'Capybaras eat their own droppings to recover gut bacteria that help them break down grass.', 'The maximum lifespan is 8 to 10 years, and captive animals may reach 12.', 'They are strong swimmers that can stay submerged for minutes at a time.']::text[], null, null, null, 1.2, 50, 1.2, 0.6, '8-12 years', false, false, array['#9c7b52', '#33261a']::text[], '🦫', 'quadruped', 86),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000057', 'brazilian-tapir', 'Brazilian Tapir', 'Tapirus terrestris', 'Mammal', 'Amazon rainforest, river floodplains and gallery forest', 'South America', 'Vulnerable', 'Herbivore', 'The Brazilian tapir, also called the lowland or South American tapir, is the largest native land mammal of South America, an odd-toed ungulate of Amazonian forest with a flexible snout it uses to pull down leaves, shoots and fruit. It keeps close to water, swimming and diving readily and following rivers between patches of forest. Numbers are falling as forest is cleared and the animals are hunted.', array['Body length is 1.8 to 2.5 metres, shoulder height 77 to 108 centimetres and weight around 225 kilograms.', 'Its snout is a fusion of nose and upper lip, used both to grasp foliage and to snorkel.', 'The lifespan is about 25 to 30 years.', 'It is a major seed disperser, carrying large seeds far from the parent tree.']::text[], null, null, null, 2.2, 225, 2.2, 0.9, '25-30 years', false, false, array['#6b5544', '#221a13']::text[], '🦛', 'quadruped', 58),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000058', 'jaguar', 'Jaguar', 'Panthera onca', 'Mammal', 'Amazonia, Pantanal wetlands and Central American forest', 'South America', 'Near Threatened', 'Carnivore', 'The jaguar is the largest cat of the Americas and the only Panthera species there, a stocky, short-tailed hunter whose rosettes enclose smaller spots. It kills large prey with a bite straight through the skull between the ears, and it swims well enough to take caiman and turtles in rivers and flooded forest. The biggest males reach 158 kilograms, and the species is listed as Near Threatened.', array['Body length runs 1.12 to 1.85 metres from nose to the base of the tail, and most adults weigh 56 to 96 kilograms.', 'It stands 57 to 81 centimetres at the shoulder.', 'Jaguars rarely live beyond 11 years in the wild, though captive animals may reach 22.', 'Unlike most cats, jaguars hunt in and around water and regularly take caiman and turtles.']::text[], null, null, null, 1.7, 80, 1.7, 0.7, '11-22 years', false, false, array['#d3a04a', '#1c1712']::text[], '🐆', 'quadruped', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000059', 'ocelot', 'Ocelot', 'Leopardus pardalis', 'Mammal', 'Neotropical forest, thorn scrub and mangrove from Texas to Argentina', 'South America', 'Least Concern', 'Carnivore', 'The ocelot is the largest of the spotted Leopardus cats, patterned with chains of dark blotches that run into stripes along the neck and shoulders. It hunts at night and mostly alone, taking rodents, opossums, reptiles and birds along trails it reuses again and again. Adults stand about 45 centimetres at the shoulder and weigh 7 to 15.5 kilograms.', array['Head and body measure 55 to 100 centimetres, with a further 30 to 45 centimetres of tail.', 'Ocelots live about 7 to 10 years in the wild, and captive animals have reached 21.', 'The spotted coat was once so valuable that tens of thousands of skins were traded every year.', 'They sleep in dense thickets by day and are rarely seen even where they are common.']::text[], null, null, null, 0.8, 12, 0.8, 0.45, '7-20 years', false, false, array['#c78d43', '#221a10']::text[], '🐆', 'quadruped', 72),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000060', 'serval', 'Serval', 'Leptailurus serval', 'Mammal', 'African grassland, wetland and highland moor', 'Africa', 'Least Concern', 'Carnivore', 'The serval is a slender African cat with very long legs, a small head and the largest ears, relative to body size, of any cat. It hunts by listening, then leaps over two metres into the air to land on rodents in tall grass with both forefeet. Up to 90 percent of what it catches weighs less than 200 grams, though it also takes birds, frogs, hares and young antelope.', array['It stands 54 to 62 centimetres at the shoulder, has a head-and-body length of 67 to 100 centimetres and weighs 8 to 18 kilograms.', 'Servals leap over 2 metres above the ground to pounce and can catch birds in flight.', 'Life expectancy is about 10 years in the wild and up to 20 in captivity.', 'A serval''s hearing is sharp enough to locate rodents moving underground.']::text[], null, null, null, 0.85, 12, 0.85, 0.58, '10-20 years', false, false, array['#d6b471', '#1f1a12']::text[], '🐆', 'quadruped', 64),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000061', 'caracal', 'Caracal', 'Caracal caracal', 'Mammal', 'African savanna, scrub and semi-desert, reaching into Asia', 'Africa', 'Least Concern', 'Carnivore', 'The caracal is a compact, long-legged cat with black tufts on the tips of its ears and a plain reddish-tan coat. It is best known for leaping more than three metres to swat birds out of the air, and it also takes rodents, hyraxes and small antelope. Adults stand 40 to 50 centimetres at the shoulder and weigh 7.2 to 19 kilograms.', array['Males weigh 7.2 to 19 kilograms and females 7 to 15.9 kilograms.', 'The black ear tufts are about 4.5 centimetres long and are thought to help direct sound toward the ear.', 'Wild caracals average around 12 years, and captive animals have reached 20.', 'It can leap more than 3 metres up from a standing start to take a bird on the wing.']::text[], null, null, null, 0.9, 13, 0.9, 0.45, '12-20 years', false, false, array['#c08b52', '#241a12']::text[], '🐆', 'quadruped', 62),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000062', 'fennec-fox', 'Fennec Fox', 'Vulpes zerda', 'Mammal', 'Sahara desert and North African sandy steppe', 'Africa', 'Least Concern', 'Omnivore', 'The fennec fox is the smallest canid, a nocturnal desert specialist whose ears can be ten centimetres long and which gives off heat as well as picking up the sound of prey under sand. It lives in family groups in burrows dug into dunes and stable sand, emerging at night to hunt insects and small vertebrates and to dig for roots. Its kidneys are efficient enough that it can go without drinking free water.', array['Females weigh 1 to 1.9 kilograms with a head-to-body length of 34.5 to 39.5 centimetres; males are slightly larger.', 'The average lifespan in the wild is about 10 years, and up to 14 in captivity.', 'Fennec foxes are strictly nocturnal, active in the cool hours of the desert night.', 'Pups are taken by eagle-owls and other desert predators, so litters are raised in deep burrows.']::text[], null, null, null, 0.4, 1.5, 0.4, 0.2, '10-14 years', false, false, array['#e0c9a4', '#3a2c1e']::text[], '🦊', 'quadruped', 81),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000063', 'bactrian-camel', 'Bactrian Camel', 'Camelus bactrianus', 'Mammal', 'Central Asian steppe and desert; wild population in the Gobi', 'Asia', 'Endangered', 'Herbivore', 'The Bactrian camel is the two-humped camel of Central Asia, kept as a pack and milk animal for millennia along the Silk Road and still herded in large numbers in Mongolia, China and Kazakhstan. Its humps store fat rather than water, and it tolerates hard frost and desert heat alike, drinking up to 130 litres at a sitting after a dry spell. Wild Bactrian camels, a separate species rather than the ancestor of the domestic form, survive in the Gobi in small numbers and are listed as Endangered.', array['Shoulder height is 160 to 180 centimetres, the top of the humps sits around 213 centimetres, and males weigh about 600 kilograms.', 'Body mass ranges from 300 to 1,000 kilograms, and a working camel can carry 170 to 250 kilograms.', 'The humps are fat, not water, and shrink and flop sideways when the animal is short of food.', 'The lifespan is estimated at up to 50 years in the wild, averaging around 30.']::text[], null, null, null, 3, 600, 3, 2.1, '30-50 years', false, false, array['#b98d5e', '#3a2a1c']::text[], '🐫', 'quadruped', 76),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000064', 'przewalskis-horse', 'Przewalski''s Horse', 'Equus ferus przewalskii', 'Mammal', 'Mongolian and Kazakh steppe; reintroduced herds on protected reserves', 'Asia', 'Endangered', 'Herbivore', 'Przewalski''s horse is the last truly wild horse, a stocky dun animal with a pale belly, dark legs and a short erect mane that was once extinct in the wild and has been rebuilt from zoo-bred stock. It has never been domesticated and carries 33 pairs of chromosomes to the domestic horse''s 32. Every animal alive descends from about fourteen founders caught between 1910 and 1960.', array['It stands about 12 to 14 hands, roughly 1.2 to 1.4 metres, and weighs around 300 kilograms.', 'Declared extinct in the wild in the 1960s, it was reintroduced to Mongolia from the 1990s onward.', 'The species has 33 chromosome pairs, one more than a domestic horse.', 'Captive animals have lived into their mid thirties, well beyond the usual wild lifespan.']::text[], null, null, null, 2.1, 300, 2.1, 1.4, '25-30 years', false, false, array['#a98a5f', '#2c2417']::text[], '🐎', 'quadruped', 68)
on conflict (slug) do update set
  name = excluded.name,
  latin_name = excluded.latin_name,
  category = excluded.category,
  habitat = excluded.habitat,
  region = excluded.region,
  conservation_status = excluded.conservation_status,
  diet = excluded.diet,
  description = excluded.description,
  fun_facts = excluded.fun_facts,
  model_url = excluded.model_url,
  image_url = excluded.image_url,
  sound_url = excluded.sound_url,
  scale_ratio = excluded.scale_ratio,
  weight_kg = excluded.weight_kg,
  length_m = excluded.length_m,
  height_m = excluded.height_m,
  lifespan_years = excluded.lifespan_years,
  is_prehistoric = excluded.is_prehistoric,
  premium = excluded.premium,
  accent = excluded.accent,
  emoji = excluded.emoji,
  silhouette = excluded.silhouette,
  popularity = excluded.popularity;

-- Sanity check: should report 64.
-- select count(*) as seeded_species from public.animals;

-- Sanity check: species per region.
-- select region, count(*) from public.animals group by region order by region;
